INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N078-01','CN0336','S078-01','生产工艺及边界','现有工程202单元','废FCC 251-017-50采用干式磁选筛分；低磁产品7800、细料9700（6778内部陶粒、2922水泥用途）为报告设计量，高磁物料危废外送。未直接证实202单元无生产废水。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N078-02','CN0336','S078-01','共享站水量冲突','图2-6及204现状段','估算进水59548.5t/a（内部49548.5、外收10000），剩余处理能力40451.5t/a估算；图2-6合计69448.5另列38345回用；段落排水31103.5m³/a。差9900不强行配平；均非实际水表量。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N078-03','CN0336','S078-01','设备及药剂','图2-11、表2-27','纤维球2台φ1000×3000、活性炭2台φ1600×3000；提升泵20m³/h H17.2 3kW，反洗泵2台30m³/h H15 4kW，气浮泵15m³/h H40 5.5kW；PAC67.6、PAM1.44、5%稀盐酸72t/a报告年耗，年份未明。不得用设计量推算单位成本。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N078-04','CN0336','S078-01','监测及单位矛盾','2024-07-30监测及排水段','历史监测列值见M078-001–008；报告另将园区50/5排放浓度写mg/m³且列0.0016/0.00016t/a，单位和数量级可疑，未作排放负荷依据。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N078-05','CN0336','turn787991search0','有效许可边界','官方名录','LN2107270129，2025-11-13至2027-09-13，HW50 25000t/a；HW08及其他油水类别独立。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N078-06','CN0337','turn787991search0','许可边界','官方名录','LN2104210140，有效期2024-04-11至2029-04-10；HW50分项2000t/a，多类别合计20万t/a，不等于专线产能。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
